const feedStatuses = $input.all();

const ERROR_EXPLANATIONS = {
  'DUPLICATE_VARIATION_ATTRIBUTE': {
    what_rejected: 'Two or more child listings share the same variation value.',
    why: 'Amazon requires each child in a variation family to have a unique value. For example, two items cannot both be listed as Red.',
    what_to_fix: 'Check your child listings and ensure each one has a different color, size, or other variation value. Remove or reassign the duplicate.',
    needs_seller_support: false,
    estimated_time: '1-2 hours'
  },
  'UNSUPPORTED_VARIATION_THEME': {
    what_rejected: 'The variation theme you used is not supported for this product type.',
    why: 'Amazon only allows specific variation themes per product category. For example, FOOTWEAR does not support ColorSize.',
    what_to_fix: 'Check the Product Type Definitions for your category and use a supported theme. Common supported themes are Color, Size, or ColorSize for clothing.',
    needs_seller_support: false,
    estimated_time: '2-4 hours'
  },
  'MISSING_REQUIRED_ATTRIBUTE': {
    what_rejected: 'A required field is missing from one of your listings.',
    why: 'Amazon requires certain attributes to be present before a variation merge can be processed. Missing attributes prevent the listing from being catalogued correctly.',
    what_to_fix: 'Open the affected listing in Seller Central and fill in all required attributes for your product type. Then resubmit.',
    needs_seller_support: false,
    estimated_time: '1-3 hours'
  },
  'PARENT_SKU_NOT_FOUND': {
    what_rejected: 'The parent SKU you specified was not found in your Amazon account.',
    why: 'Either the parent SKU does not exist, was recently deleted, or was never created as a parent listing.',
    what_to_fix: 'Verify the parent SKU exists in Seller Central under Manage Inventory. If it was deleted, you may need to recreate it or contact Seller Support.',
    needs_seller_support: true,
    estimated_time: '1-3 business days if Seller Support needed'
  },
  'INVALID_ATTRIBUTE_VALUE': {
    what_rejected: 'One or more attribute values are not valid for this product type.',
    why: 'Amazon validates attribute values against its product type schema. Values that do not match the allowed format or enum are rejected.',
    what_to_fix: 'Check the rejected attribute value and correct it to match Amazon standard format. Common issues: size values not in standard format (use XL not Extra Large), color values with special characters.',
    needs_seller_support: false,
    estimated_time: '1-2 hours'
  },
  'RELATIONSHIP_NOT_FOUND': {
    what_rejected: 'The parent-child relationship could not be established.',
    why: 'Amazon could not link the child listing to the specified parent. This usually happens when the parent SKU has not been fully processed yet.',
    what_to_fix: 'Wait 30 minutes and check if the parent listing is visible in Seller Central. If the parent exists, resubmit the feed. If not, create the parent listing first.',
    needs_seller_support: false,
    estimated_time: '30 minutes to 2 hours'
  },
  'FEED_PROCESSING_ERROR': {
    what_rejected: 'Amazon encountered an internal error while processing your feed.',
    why: 'This is an Amazon-side error, not caused by your data. It can happen during high-traffic periods or system maintenance.',
    what_to_fix: 'Wait 1 hour and resubmit the same feed. If the error persists after 3 attempts, contact Amazon Seller Support with your feed_id.',
    needs_seller_support: true,
    estimated_time: '1-24 hours'
  },
  'THROTTLED': {
    what_rejected: 'Your feed submission was throttled by Amazon.',
    why: 'Amazon limits the number of feed submissions per account within a time window.',
    what_to_fix: 'Wait at least 1 hour before resubmitting. Avoid submitting multiple feeds in quick succession.',
    needs_seller_support: false,
    estimated_time: '1-2 hours'
  }
};

return feedStatuses.map(function(feedStatusItem, index) {
  const feedStatus = feedStatusItem.json;
  // itemMatching, not raw array indexing - this is n8n's own mechanism for
  // tracing which input row produced which output, so pairing stays
  // correct even if something upstream ever reorders items.
  const submissionLog = $('Fetch Pending Submissions').itemMatching(index).json;

  if (feedStatus.error) {
    return { json: {
      decision: 'FETCH_FAILED',
      fetch_failed: true,
      feed_id: submissionLog.feed_id,
      request_id: submissionLog.request_id,
      submission_log_id: submissionLog.id,
      poll_error_message: feedStatus.error.message || 'Unknown error contacting the feed status proxy.',
      poll_error_status: feedStatus.error.status || null,
      is_complete: false
    }};
  }

  const processingReport = feedStatus.processing_report || {};
  const errors = processingReport.errors || [];

  const explainedErrors = errors.map(function(err) {
    const explanation = ERROR_EXPLANATIONS[err.message_code] || {
      what_rejected: 'Amazon returned an unrecognized error: ' + (err.message_code || 'UNKNOWN'),
      why: 'This error code is not in our known error library.',
      what_to_fix: 'Contact Amazon Seller Support with your feed_id: ' + feedStatus.feed_id + ' and this error code for assistance.',
      needs_seller_support: true,
      estimated_time: 'Unknown — depends on Seller Support response time'
    };
    return {
      message_code: err.message_code || 'UNKNOWN_ERROR',
      amazon_description: err.description || 'No description provided',
      what_rejected: explanation.what_rejected,
      why: explanation.why,
      what_to_fix: explanation.what_to_fix,
      needs_seller_support: explanation.needs_seller_support,
      estimated_time: explanation.estimated_time
    };
  });

  return { json: {
    decision: 'REPORT_PARSED',
    fetch_failed: false,
    feed_id: feedStatus.feed_id,
    request_id: submissionLog.request_id,
    submission_log_id: submissionLog.id,
    processing_status: feedStatus.processing_status,
    messages_processed: processingReport.messages_processed || 0,
    messages_successful: processingReport.messages_successful || 0,
    messages_with_error: processingReport.messages_with_error || 0,
    error_count: errors.length,
    explained_errors: explainedErrors,
    processing_report_json: processingReport,
    is_complete: feedStatus.processing_status === 'DONE' || feedStatus.processing_status === 'FATAL'
  }};
});

const items = $input.all();

// alwaysOutputData on "Fetch Pending Submissions" means a genuinely empty
// result still arrives here as one placeholder item, not zero items -
// the same gotcha this project has hit before elsewhere. A real row
// always has an id; the placeholder won't.
const realRows = items.filter(function(item) {
  return item.json && item.json.id;
});

if (realRows.length === 0) {
  return [{ json: { status: 'NO_PENDING_FEEDS', message: 'No submitted feeds found.' } }];
}

return realRows.map(function(item) {
  return { json: item.json };
});

