const items = $input.all();

return items.map(function(item) {
  const d = item.json;

  return {
    json: {
      submission_log_id: d.submission_log_id,
      poll_error_report: {
        poll_error: true,
        message: d.poll_error_message,
        status: d.poll_error_status,
        failed_at: new Date().toISOString()
      }
    }
  };
});
